package com.bank.bulk.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")
public class Account {
    @Id @Column(name = "account_id") private String accountId;
    @Column(name = "holder_name") private String holderName;
    private BigDecimal balance;
    @Version private Long version;

    protected Account() {}

    public void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient: " + balance);
        balance = balance.subtract(amount);
    }

    public void credit(BigDecimal amount) { balance = balance.add(amount); }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
}
