package com.bank.bulk.service;

import com.bank.bulk.dto.TransferRequest;
import com.bank.bulk.model.Account;
import com.bank.bulk.repository.AccountRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class SafeTransferServiceTest {

    @Mock AccountRepository accountRepo;
    @InjectMocks SafeTransferService service;

    @Test
    void shouldLockInAlphabeticalOrder() {
        Account cur = mock(Account.class);
        Account sav = mock(Account.class);
        when(cur.getAccountId()).thenReturn("CUR3001");
        when(sav.getAccountId()).thenReturn("SAV2001");

        // CUR3001 < SAV2001 alphabetically → CUR locked first
        when(accountRepo.findByIdForUpdate("CUR3001")).thenReturn(Optional.of(cur));
        when(accountRepo.findByIdForUpdate("SAV2001")).thenReturn(Optional.of(sav));

        String result = service.transferSafe(
            new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000")));

        assertThat(result).isEqualTo("SAFE_COMPLETED");

        // Verify CUR3001 was locked BEFORE SAV2001 (alphabetical order)
        InOrder inOrder = inOrder(accountRepo);
        inOrder.verify(accountRepo).findByIdForUpdate("CUR3001");  // first
        inOrder.verify(accountRepo).findByIdForUpdate("SAV2001");  // second
    }
}
